INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(29526, 'koKR', 'Może jeszcze mi się przydasz.', '', 0),
(29527, 'koKR', 'Ależ proszę, nie oceniaj sytuacji, ty półgłówku! Po prostu rzuć się w wir walki!', '', 0),
(29528, 'koKR', 'Skarvaldzie, ty nieudolny ślimaku! Wracaj i zrób się użyteczny!', '', 0),
(29529, 'koKR', 'Do... zobaczenia... wkrótce.', '', 0),
(29530, 'koKR', 'Nie ma... większej... chwały.', '', 0),
(29531, 'koKR', 'Dalronnie! Sprawdź, czy starczy ci odwagi, żeby dołączyć do mojego ataku!', '', 0),
(29532, 'koKR', 'Jarggn olkt!', '', 0),
(29533, 'koKR', 'Pfuj! Co to za nekromanta, którego powstrzymuje śmierć? Wiedziałem, że jesteś do niczego!', '', 0),
(29534, 'koKR', 'To... jeszcze... nie koniec.', '', 0),
(29535, 'koKR', 'Śmierć wojownika.', '', 0),
(29974, 'koKR', 'Pomaluję sobie twarz twoją krwią!', '', 0),
(29975, 'koKR', 'Jestem urodzonym wojownikiem!', '', 0),
(29976, 'koKR', 'Me życie dla... boga śmierci!', '', 0),
(29977, 'koKR', 'Wracam! Druga szansa, by rozłupać wam czaszki!', '', 0),
(29978, 'koKR', 'Mjul orm agn gjor!', '', 0),
(29979, 'koKR', 'Nie! Stać mnie... na więcej! Mogę...', '', 0);
